insert into public.categories (slug,name,description,image_url,sort_order,is_active) values
('wedding-souvenirs','Wedding Souvenirs','Beautiful keepsakes designed to make your wedding celebration unforgettable.','/images/wedding-souvenirs.jpg',1,true),
('birthday-gifts','Birthday Gifts','Thoughtful gifts for birthdays and milestone celebrations.','/images/products/gift-boxes-wide.jpg',2,true),
('corporate-gifts','Corporate Gifts','Elegant and professional gifts for clients, employees and business partners.','/images/products/signature-open.jpg',3,true),
('personalised-gifts','Personalised Gifts','Make your gift truly special with names, dates, messages and customised designs.','/images/signature-box.jpg',4,true),
('gift-boxes','Gift Boxes','Beautifully curated gift boxes designed for every occasion.','/images/hero-gift-boxes.jpg',5,true)
on conflict (slug) do nothing;

insert into public.products (slug,name,short_description,description,price,price_is_from,category_slug,images,occasions,is_personalisable,personalisation_fields,min_quantity,stock,lead_time_days,is_bestseller,is_featured,is_active,sort_order) values
('the-signature-box','The Signature Box','A refined edit of beautiful little luxuries.','Our house gift box: a rigid black presentation box lined with ivory tissue and filled with a premium selection of carefully chosen keepsakes, finished with a satin ribbon and a gold-foiled card. Ready to give the moment it arrives.',58,false,'gift-boxes',array['/images/signature-box.jpg','/images/products/signature-open.jpg','/images/products/signature-detail.jpg']::text[],array['birthdays','anniversaries','weddings']::text[],true,'[{"key":"name","label":"Name or initials","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,4,true,true,true,1),
('wedding-favour-set','Wedding Favour Set','Elegant keepsakes for your guests to treasure.','Ivory favour boxes tied with a champagne ribbon and a gold wax seal, finished with a name or "with love" card. Price shown is per favour for orders of 20+; personalised tags and bespoke ribbon colours available.',4.5,true,'wedding-souvenirs',array['/images/wedding-souvenirs.jpg','/images/products/wedding-cluster.jpg','/images/products/wedding-card.jpg']::text[],array['weddings','anniversaries']::text[],true,'[{"key":"name","label":"Couple names","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"date","label":"Date","type":"date"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,20,null,14,true,true,true,2),
('the-celebration-box','The Celebration Box','A beautiful way to mark their special day.','A champagne-ivory gift box with a satin bow, filled with a curated set of treats and keepsakes for birthdays and milestone moments. Add a name and message to make it theirs.',48,false,'birthday-gifts',array['/images/hero-gift-boxes.jpg','/images/products/gift-boxes-wide.jpg','/images/products/gift-boxes-tissue.jpg']::text[],array['birthdays','graduations']::text[],true,'[{"key":"name","label":"Name or initials","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,5,true,true,true,3),
('the-wedding-box','The Wedding Box','Elegant gifts for couples, bridesmaids and groomsmen.','A luxury keepsake box for the people who matter most on your wedding day. Choose names and a date, and we will present it with gold detailing and a handwritten-style card.',72,false,'gift-boxes',array['/images/products/gift-boxes-wide.jpg','/images/products/wedding-card.jpg','/images/hero-gift-boxes.jpg']::text[],array['weddings']::text[],true,'[{"key":"name","label":"Name or initials","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"date","label":"Date","type":"date"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,7,true,false,true,4),
('the-corporate-box','The Corporate Box','Premium gifting for clients and business partners.','A polished presentation box designed to make a lasting impression. Add your logo and a personal note. Volume pricing is available — request a quote for 20+ boxes.',65,false,'corporate-gifts',array['/images/products/signature-open.jpg','/images/signature-box.jpg','/images/products/signature-detail.jpg']::text[],array['corporate']::text[],true,'[{"key":"name","label":"Recipient or company name","type":"text","required":false,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"logo_note","label":"Logo / branding details","type":"textarea","maxLength":200,"placeholder":"Describe your logo or send it to us after ordering"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,10,true,false,true,5),
('the-luxury-box','The Luxury Box','Our premium gifting experience.','The very best of LICHT SIGNATURE: an oversized rigid box, layered tissue, hand-tied ribbon and our most indulgent selection of keepsakes. For the gift that is remembered.',120,false,'gift-boxes',array['/images/products/signature-open.jpg','/images/hero-gift-boxes.jpg','/images/signature-box.jpg']::text[],array['weddings','anniversaries','corporate']::text[],true,'[{"key":"name","label":"Name or initials","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,7,true,true,true,6),
('personalised-luxury-gift-box','Personalised Luxury Gift Box','Elegant gift box customised with a name or special message.','Start with our luxury box and make it entirely yours: names, initials, dates, a message and a gold-foil monogram. Every detail is approved with you before we begin.',62,true,'personalised-gifts',array['/images/signature-box.jpg','/images/products/signature-detail.jpg','/images/products/signature-open.jpg']::text[],array['birthdays','anniversaries','weddings','baby-showers']::text[],true,'[{"key":"name","label":"Name or initials","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"date","label":"Date","type":"date"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,6,true,true,true,7),
('guest-favour-gift-box','Guest Favour Gift Box','Individually boxed guest gifts with a name tag.','Small, beautifully presented gift boxes with a personalised tag for each guest — perfect for place settings. Minimum order of 20.',6.9,false,'wedding-souvenirs',array['/images/products/wedding-cluster.jpg','/images/wedding-souvenirs.jpg','/images/products/wedding-card.jpg']::text[],array['weddings','christenings']::text[],true,'[{"key":"name","label":"Tag wording","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Thank you for celebrating with us"},{"key":"date","label":"Date","type":"date"}]'::jsonb,20,null,14,true,false,true,8),
('birthday-keepsake-box','Birthday Keepsake Box','A keepsake box for children, teens and adults.','A gift box with room for little treasures — add a name, age and message and we will dress it for the occasion.',42,false,'birthday-gifts',array['/images/products/gift-boxes-tissue.jpg','/images/hero-gift-boxes.jpg','/images/products/gift-boxes-wide.jpg']::text[],array['birthdays']::text[],true,'[{"key":"name","label":"Name or initials","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"age","label":"Age / milestone","type":"text","maxLength":10},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,5,false,false,true,9),
('anniversary-memory-set','Anniversary Memory Set','A beautiful keepsake for couples and loved ones.','A gold-foiled keepsake presented in an ivory box, personalised with names and the date you celebrate.',54,false,'personalised-gifts',array['/images/products/wedding-card.jpg','/images/products/wedding-cluster.jpg','/images/signature-box.jpg']::text[],array['anniversaries']::text[],true,'[{"key":"name","label":"Names","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"date","label":"Date","type":"date"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,5,false,false,true,10),
('christening-keepsake-set','Christening Keepsake Set','Elegant keepsakes for a meaningful occasion.','A soft ivory keepsake set to commemorate a christening or dedication — personalised with the child’s name and date.',36,false,'personalised-gifts',array['/images/wedding-souvenirs.jpg','/images/products/wedding-card.jpg','/images/products/gift-boxes-tissue.jpg']::text[],array['christenings','baby-showers']::text[],true,'[{"key":"name","label":"Child''s name","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"date","label":"Date","type":"date"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,1,null,5,false,false,true,11),
('staff-appreciation-gift','Staff Appreciation Gift','A considered thank-you for your team.','A neat presentation box with a premium selection and a personalised thank-you card. Minimum order of 10; ask us about branding.',28,false,'corporate-gifts',array['/images/products/signature-detail.jpg','/images/products/signature-open.jpg','/images/signature-box.jpg']::text[],array['corporate']::text[],true,'[{"key":"name","label":"Company name","type":"text","required":true,"maxLength":30,"placeholder":"e.g. Amara & Tunde"},{"key":"logo_note","label":"Logo / branding details","type":"textarea","maxLength":200,"placeholder":"Describe your logo or send it to us after ordering"},{"key":"message","label":"Special message","type":"textarea","maxLength":120,"placeholder":"A short message for the card (optional)"}]'::jsonb,10,null,10,false,false,true,12)
on conflict (slug) do nothing;

